# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">İSLAM\'DA AİLE KURUMU VE KARŞILIKLI GÖREVLER (TDB.1.3)</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Ailenin Temel İlkeleri (Rûm 21)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Toplumun en küçük ve en sağlam yapı taşıdır.</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Nikâh akdiyle meşru ve hukuki temel kazanır.</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• Sekînet: Aile yuvasında huzur ve güven bulma</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Meveddet: Eşler ve bireyler arası karşılıklı sevgi</text>\n  <text x="40" y="186" font-size="11" fill="#334155">• Rahmet: Şefkat, merhamet ve anlayış bağı</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#1e40af">"Sizin en hayırlınız, ailesine en hayırlı olandır."</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Anne-Baba ve Çocukların Hakları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Anne-Babanın Görevleri: Güzel isim koymak, helal</text>\n  <text x="375" y="118" font-size="11" fill="#334155">  rızıkla beslemek, iyi eğitim ve güzel ahlak vermek</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Evlatların Görevleri (İsrâ 23-24): Anne-babaya</text>\n  <text x="375" y="162" font-size="11" fill="#334155">  ihsanda bulunmak, "öf" bile dememek, tatlı söz</text>\n  <text x="375" y="184" font-size="11" fill="#334155">• Yaşlandıklarında onlara şefkat kanatlarını germek</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">"Hiçbir baba evladına güzel terbiyeden üstün miras..."</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">AKRABALIK BAĞLARI (SILA-İ RAHİM) VE KOMŞULUK HAKKI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">1. Sıla-i Rahim (Akrabayı Gözetmek)</text>\n  <text x="40" y="98" font-size="11" fill="#334155">• Kan ve evlilik yoluyla oluşan yakınları ziyaret etmek</text>\n  <text x="40" y="120" font-size="11" fill="#334155">• Hal ve hatırlarını sormak, sevinç ve kederi paylaşmak</text>\n  <text x="40" y="142" font-size="11" fill="#334155">• İnfak ve sadakada önce yoksul akrabayı gözetmek</text>\n  <text x="40" y="164" font-size="11" fill="#334155">• Rızkın bereketlenmesine ve ömrün huzurlu olmasına</text>\n  <text x="40" y="184" font-size="11" fill="#334155">  vesile olur; akrabalık bağını koparmak yasaklanmıştır.</text>\n  <text x="182" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#92400e">Nisâ 1 ve Nahl 90: Yakınlara İyilik Emri</text>\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fdf2f8" stroke="#ec4899"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be185d">2. Komşuluk Ahlakı ve Hakları</text>\n  <text x="375" y="98" font-size="11" fill="#334155">• Komşuya el ve dil ile zarar vermemek (güven vermek)</text>\n  <text x="375" y="120" font-size="11" fill="#334155">• "Komşusu açken tok yatan bizden değildir" bilinci</text>\n  <text x="375" y="142" font-size="11" fill="#334155">• Pişirilen yemekten ikram etmek, selamlaşmak</text>\n  <text x="375" y="164" font-size="11" fill="#334155">• Hastalandığında ziyaret etmek, cenazesine katılmak</text>\n  <text x="375" y="186" font-size="11" fill="#334155">• Ayıp ve kusurlarını örtmek, gürültüyle rahatsız etmemek</text>\n  <text x="517" y="218" text-anchor="middle" font-size="11" font-weight="bold" fill="#9d174d">Cebrail\'in (as) Üzerinde Titrediği Komşu Hakkı</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">KOMŞULARIN HAK DERECELERİ VE SOSYAL DAYANIŞMA</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6"/>\n  <text x="125" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">Üç Haklı Komşu</text>\n  <text x="34" y="100" font-size="11" fill="#334155">• Hem Müslüman, hem akraba</text>\n  <text x="34" y="120" font-size="11" fill="#334155">  hem de komşu olan kişi:</text>\n  <text x="34" y="146" font-size="11" fill="#1e40af">  1) Komşuluk hakkı</text>\n  <text x="34" y="166" font-size="11" fill="#1e40af">  2) Akrabalık hakkı</text>\n  <text x="34" y="186" font-size="11" fill="#1e40af">  3) Din kardeşliği hakkı</text>\n  <text x="125" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#1d4ed8">En Kapsamlı Sosyal Hak</text>\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e"/>\n  <text x="350" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#15803d">İki Haklı Komşu</text>\n  <text x="259" y="100" font-size="11" fill="#334155">• Akraba olmayan ancak</text>\n  <text x="259" y="120" font-size="11" fill="#334155">  Müslüman olan komşu:</text>\n  <text x="259" y="146" font-size="11" fill="#166534">  1) Komşuluk hakkı</text>\n  <text x="259" y="166" font-size="11" fill="#166534">  2) Din kardeşliği hakkı</text>\n  <text x="259" y="190" font-size="11" fill="#334155">• Nisâ 36: Yakın ve uzak komşu</text>\n  <text x="350" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#15803d">Kardeşlik ve Komşuluk Bağı</text>\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308"/>\n  <text x="575" y="72" text-anchor="middle" font-size="12" font-weight="bold" fill="#a16207">Bir Haklı Komşu</text>\n  <text x="484" y="100" font-size="11" fill="#334155">• Müslüman ve akraba olmayan</text>\n  <text x="484" y="120" font-size="11" fill="#334155">  (gayrimüslim) komşu:</text>\n  <text x="484" y="146" font-size="11" fill="#92400e">  1) Komşuluk ve insanlık hakkı</text>\n  <text x="484" y="170" font-size="11" fill="#334155">• İslam\'da inancı ne olursa olsun</text>\n  <text x="484" y="190" font-size="11" fill="#334155">  her komşunun hakkı korunur.</text>\n  <text x="575" y="218" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#a16207">Evrensel Komşuluk Hukuku</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
